function isIgnoredFile(file) {
  return IGNORED_FILES.has(file);
}

function isAnalysisFile(file) {
  return !!file && ANALYSIS_FILES.has(file);
}

function buildAutoExecutionPipeline(functionName) {
  if (functionName === "POST /chat callback") {
    return {
      found: true,
      reply: `🚀 Automatic Execution Pipeline

POST /chat callback()

↓ validate message
↓ remember(message)
↓ loadProfile()

🧠 Project Brain
  ├─ found → return Project Brain reply
  └─ not found → continue to normal AI pipeline

↓ optional search()
↓ build AI messages
↓ OpenRouter request
↓ history.push(assistant reply)
↓ saveMemory()
↓ res.json()`
    };
  }

  if (functionName === "answerProjectQuestion") {
    return {
      found: true,
      reply: `🧠 Project Brain Pipeline

answerProjectQuestion()

↓ resolveFunctionName()
↓ analyze project question
↓ return Project Brain result`
    };
  }

  if (functionName === "buildAutoExecutionPipeline") {
    return {
      found: true,
      reply: `🚀 Automatic Execution Pipeline

buildAutoExecutionPipeline()

↓ called by answerProjectQuestion()
↓ receives the resolved project keyword
↓ checks for runtime-specific pipeline
↓ otherwise traces projectGraph
↓ filters ignored files
↓ filters analysis-only files
↓ builds execution pipeline reply
↓ returns { found, reply }`
    };
  }

  const tracedChain = projectGraph.traceCallees(functionName);

  const ignoredCalls = tracedChain.filter(item =>
    isIgnoredFile(item.file) ||
    isIgnoredFile(item.calleeFile)
  );

  const analysisCalls = tracedChain.filter(item =>
    !isIgnoredFile(item.file) &&
    !isIgnoredFile(item.calleeFile) &&
    isAnalysisFile(item.calleeFile) &&
    item.callee !== "answerProjectQuestion"
  );

  const chain = tracedChain
    .filter(item =>
      !isIgnoredFile(item.file) &&
      !isIgnoredFile(item.calleeFile)
    )
    .filter(item =>
      !isAnalysisFile(item.calleeFile) ||
      item.callee === "answerProjectQuestion"
    )
    .filter(item =>
      !(item.callee === "answerProjectQuestion" && item.depth > 0)
    );

  const lines = [];

  for (const item of chain) {
    const indent = "  ".repeat(item.depth);

    const location =
      item.file && item.callLine
        ? ` — ${item.file}:${item.callLine}`
        : "";

    lines.push(
      `${indent}↓ ${item.callee}()${location}`
    );
  }

  const sections = [
    `🚀 Automatic Execution Pipeline

${functionName}()

${lines.length > 0
  ? lines.join("\n")
  : "No application-level project function calls detected."}`
  ];

  if (analysisCalls.length > 0) {
    sections.push(
      `🧠 Analysis calls excluded:

${analysisCalls
  .map(item => {
    const location =
      item.file && item.callLine
        ? ` — ${item.file}:${item.callLine}`
        : "";

    return `• ${item.callee}()${location}`;
  })
  .join("\n")}`
    );
  }

  if (ignoredCalls.length > 0) {
    sections.push(
      `🚫 Ignored calls excluded:

${ignoredCalls
  .map(item => `• ${item.callee}()`)
  .join("\n")}`
    );
  }

  return {
    found: true,
    reply: sections.join("\n\n")
  };
}

function traceFunction(functionName) {

  const callers = projectSearch.findCallers(functionName);

  if (callers.length === 0) {
    return {
      found: false
    };
  }

  const sections = callers.map(c => {

    const fullPath = path.join(process.cwd(), c.file);

    if (!fs.existsSync(fullPath)) {
      return `• ${c.file}
  Line ${c.line}`;
    }

    const lines = fs.readFileSync(fullPath, "utf8").split("\n");

    const start = Math.max(0, c.line - 2);
    const end = Math.min(lines.length, c.line + 1);

    const context = lines
      .slice(start, end)
      .map((line, index) => {
        const lineNumber = start + index + 1;
        return `${lineNumber}  ${line}`;
      })
      .join("\n");

    return `${c.file}
Line ${c.line}

${context}`;
  });

  return {
    found: true,
    reply:
`🔗 Call Chain

Function:
${functionName}()

Total callers:
${callers.length}

Called from:

${sections.join("\n\n")}`
  };

}

.map((line, index) => {
  const lineNumber = start + index + 1;
  return `${lineNumber}  ${line}`;
})

function buildTree(index, fnName, depth = 0, visited = new Set()) {

  const indent = "│   ".repeat(depth);

  if (visited.has(fnName)) {
    return indent + "└── " + fnName + "() (recursive)\n";
  }

  visited.add(fnName);

  let output = "";

  for (const file of index) {

    const functions = [
      ...(file.functions || []),
      ...(file.arrowFunctions || [])
    ];

    const fn = functions.find(f => f.name === fnName);

    if (!fn) continue;

    if (!fn.calls || fn.calls.length === 0) {
      return "";
    }

    for (const call of fn.calls) {

      output += indent + "├── " + call + "()\n";

      output += buildTree(
        index,
        call,
        depth + 1,
        new Set(visited)
      );

    }

    break;

  }

  return output;

}

function buildCallHierarchy(functionName) {

  const index = projectSearch.loadIndex();

  for (const file of index) {

    const functions = [
      ...(file.functions || []),
      ...(file.arrowFunctions || [])
    ];

    const fn = functions.find(f => f.name === functionName);

    if (!fn) continue;

    return {
      found: true,
      reply:
`🌳 Call Hierarchy

${functionName}()
${buildTree(index, functionName)}`
    };

  }

  return {
    found: false
  };

}

function getFunctionInfo(file, functionName) {
  const index = projectSearch.loadIndex();

  const target = index.find(f => f.file === file);

  if (!target) {
    return null;
  }

  return [
    ...(target.functions || []),
    ...(target.arrowFunctions || [])
  ].find(fn => fn.name === functionName) || null;
}

function buildRecursiveImpact(functionName) {
  const results = [];
  const queue = [
    {
      functionName,
      depth: 0,
      path: [functionName]
    }
  ];

  const visited = new Set();

  while (queue.length > 0) {
    const current = queue.shift();

    if (current.depth >= MAX_DEPTH) {
      continue;
    }

    const callers = projectSearch.findCallers(current.functionName);

    for (const caller of callers) {
      const key =
        `${caller.caller}|${caller.file}|${caller.line}|${current.functionName}`;

      if (visited.has(key)) {
        continue;
      }

      visited.add(key);

      const nextDepth = current.depth + 1;

      // Do not record circular call paths as additional impact.
      if (current.path.includes(caller.caller)) {
        continue;
      }

      const nextPath = [
        ...current.path,
        caller.caller
      ];

      results.push({
        functionName: caller.caller,
        file: caller.file,
        line: caller.line,
        depth: nextDepth,
        via: current.functionName,
        path: nextPath
      });

      if (nextDepth < MAX_DEPTH) {
        queue.push({
          functionName: caller.caller,
          depth: nextDepth,
          path: nextPath
        });
      }
    }
  }

  return results;
}

function analyzeDeepFunctionImpact(functionName) {
  const results = projectSearch.findFunction(functionName);

  if (results.length === 0) {
    return {
      found: false
    };
  }

  const functionInfo = results[0];

  const impact = buildRecursiveImpact(functionName);

  const directCallers = impact.filter(
    item => item.depth === 1
  );

  const indirectCallers = impact.filter(
    item => item.depth > 1
  );

  const uniqueFunctions = new Set(
    impact.map(item => item.functionName)
  );

  const directCallerFunctions = new Set(
    directCallers.map(item => item.functionName)
  );

  const directCallSites = directCallers.length;

  const indirectCallSites = indirectCallers.length;

  const affectedFiles = new Set(
    impact.map(item => item.file)
  );

  const maxDepth =
    impact.length > 0
      ? Math.max(...impact.map(item => item.depth))
      : 0;

  let risk = "LOW";

  if (
    uniqueFunctions.size >= 8 ||
    affectedFiles.size >= 3 ||
    maxDepth >= 5
  ) {
    risk = "HIGH";
  } else if (
    uniqueFunctions.size > 0
  ) {
    risk = "MEDIUM";
  }

  const directText =
    directCallers.length > 0
      ? directCallers
          .map(item =>
            `• ${item.functionName}() — ${item.file}:${item.line}`
          )
          .join("\n")
      : "No direct callers found.";

  let recursiveText =
    "No recursive callers beyond level 1.";

  if (indirectCallers.length > 0) {
    recursiveText = indirectCallers
      .map(item =>
        `• Level ${item.depth}: ${item.functionName}() — ${item.file}:${item.line} → ${item.via}()`
      )
      .join("\n");
  }

  const affectedFileText =
    affectedFiles.size > 0
      ? [...affectedFiles]
          .map(file => `• ${file}`)
          .join("\n")
      : "No affected files found.";

  return {
    found: true,
    reply:
`🧠 Deep Function Impact Analysis

Function:
${functionName}()

📍 Defined in:
${functionInfo.file} — Line ${functionInfo.line}

🔗 Direct callers:
${directText}

🌐 Recursive impact:
${recursiveText}

📊 Impact Summary:
• Direct caller functions: ${directCallerFunctions.size}
• Direct call sites: ${directCallSites}
• Recursive call sites: ${indirectCallSites}
• Unique affected functions: ${uniqueFunctions.size}
• Affected files: ${affectedFiles.size}
• Maximum caller depth: ${maxDepth}
• Maximum analysis depth: ${MAX_DEPTH}

📁 Affected files:
${affectedFileText}

⚠️ Risk:
${risk}

Changing ${functionName}() may affect ${directCallerFunctions.size} direct caller function${directCallerFunctions.size === 1 ? "" : "s"} and ${uniqueFunctions.size} unique affected caller function${uniqueFunctions.size === 1 ? "" : "s"} across ${affectedFiles.size} file${affectedFiles.size === 1 ? "" : "s"}.`
  };
}

function traceDependencies(functionName, visited = new Set()) {
  if (visited.has(functionName)) {
    return [];
  }

  visited.add(functionName);

  const callers = projectSearch.findCallers(functionName);

  let result = [];

  for (const caller of callers) {
    result.push(caller);

    result.push(
      ...traceDependencies(caller.caller, visited)
    );
  }

  return result;
}

function dependencyTree(fileName) {

  const index = projectSearch.loadIndex();

  const file = index.find(f => f.file.endsWith(fileName));

  if (!file) {
    return {
      found: false
    };
  }

  let reply = `🌳 Dependency Tree\n\n${file.file}\n`;

  if (file.requires.length === 0) {
    reply += "\n(No dependencies)";
  } else {

    for (const dep of file.requires) {
      reply += `├── ${dep}\n`;
    }

  }

  return {
    found: true,
    reply
  };

}

function explainFunctionExecution(functionName) {
  const direct = projectGraph.findCallees(functionName);

  const functionInfo = projectSearch.findFunction(functionName);

  if (functionInfo.length === 0) {
    return {
      found: false,
      reply: `❌ I couldn't find ${functionName}() in the project.`
    };
  }

  const lines = [];

  lines.push("🚀 Function Call Map");
  lines.push("");
  lines.push(`${functionName}()`);
  lines.push("");

  if (direct.length === 0) {
    lines.push("└─ No other project functions detected.");
  } else {
    for (const item of direct) {
      const location =
        item.file
          ? ` — ${item.file}`
          : "";

      lines.push(
        `↓ ${item.callee}()${location}`
      );
    }
  }

  lines.push("");
  lines.push("ℹ️ This shows direct project-function calls.");
  lines.push(
    "Conditional branches may execute only when their conditions match."
  );

  return {
    found: true,
    reply: lines.join("\n")
  };
}

function explainExecution(topic) {
  const key = topic.toLowerCase().trim();

  if (
    key.includes("chat") ||
    key.includes("message") ||
    key.includes("/chat")
  ) {
    return {
      found: true,
      reply:
`🚀 Chat Runtime Execution Flow

${flows.chat.map((step, i) => `${i + 1}. ${step}`).join("\n")}

🔀 Main decision:

POST /chat
   ↓
Project Brain
   ├─ found → return Project Brain reply
   └─ not found → continue to normal AI pipeline`
    };
  }

  if (
    key.includes("startup") ||
    key.includes("start")
  ) {
    return {
      found: true,
      reply:
`🚀 Startup Execution Flow

${flows.startup.map((step, i) => `${i + 1}. ${step}`).join("\n")}`
    };
  }

  const index = projectSearch.loadIndex();

  for (const file of index) {
    const functions = [
      ...(file.functions || []),
      ...(file.arrowFunctions || [])
    ];

    const match = functions.find(
      fn =>
        fn.name.toLowerCase() === key ||
        key.includes(fn.name.toLowerCase())
    );

    if (match) {
      return explainFunctionExecution(match.name);
    }
  }

  return {
    found: false
  };
}

function buildExecutionGraph(functionName) {
  if (!functionName) {
    return {
      found: false
    };
  }

  const callers = projectGraph.traceCallers(functionName);

  const lines = [];

  lines.push("🕸 Execution Path");
  lines.push("");
  lines.push(`Target: ${functionName}()`);
  lines.push("");

  if (callers.length === 0) {
    lines.push("└── No project callers detected");
  } else {
    for (const item of callers) {
      const indent = "  ".repeat(item.depth);

      lines.push(
        `${indent}└── ${item.caller}() — ${item.file}:${item.line}`
      );
    }
  }

  return {
    found: true,
    reply: lines.join("\n")
  };
}

function buildExecutionPipeline(feature) {

  const keyword = feature.toLowerCase();

  const files = projectSearch.loadIndex();

  const pipeline = [];

  for (const file of files) {

    if (!file.file.toLowerCase().includes(keyword)) continue;

    pipeline.push(file.file);

  }

  if (pipeline.length === 0) {
    return {
      found: false
    };
  }

  return {
    found: true,
    reply:
`🚀 Execution Pipeline

Feature:
${feature}

Execution Flow

Browser
   │
   ▼
POST /chat
   │
${pipeline.join("\n↓\n")}`
  };

}

function explainFeature(feature) {

  const index = projectSearch.loadIndex();

  const keyword = feature.toLowerCase();

  const files = [];

  for (const file of index) {

    const name = file.file.toLowerCase();

    if (name.includes(keyword)) {
      files.push(file.file);
      continue;
    }

    const allFunctions = [
      ...(file.functions || []),
      ...(file.arrowFunctions || [])
    ];

    if (
      allFunctions.some(fn =>
        fn.name.toLowerCase().includes(keyword)
      )
    ) {
      files.push(file.file);
    }

  }

  if (files.length === 0) {
    return {
      found: false
    };
  }

  return {
    found: true,
    reply:
`🧠 Feature Analysis

Feature:
${feature}

Files involved:

${files.map(f => "• " + f).join("\n")}

Total files:
${files.length}`
  };

}

function explainFile(fileName) {
  const files = projectSearch.loadIndex();

  const file = files.find(f =>
    f.file.toLowerCase() === fileName.toLowerCase()
  );

  if (!file) {
    return {
      found: false
    };
  }

  let reply = `📄 ${file.file}\n\n`;

  if (file.functions.length > 0) {
    reply += "Functions:\n";
    reply += file.functions.map(f => "• " + f.name + "()").join("\n");
    reply += "\n\n";
  }

  if (file.arrowFunctions.length > 0) {
    reply += "Arrow Functions:\n";
    reply += file.arrowFunctions.map(f => "• " + f.name).join("\n");
    reply += "\n\n";
  }

  if (file.requires.length > 0) {
    reply += "Dependencies:\n";
    reply += file.requires.map(r => "• " + r.module).join("\n");
  }

  return {
    found: true,
    reply
  };
}

function buildExecutionTree(functionName, visited = new Set(), depth = 0) {
  if (!functionName) return [];

  if (visited.has(functionName)) {
    return [`${"  ".repeat(depth)}↺ ${functionName}()`];
  }

  visited.add(functionName);

  const output = [];
  output.push(`${"  ".repeat(depth)}📌 ${functionName}()`);

  const callees = projectSearch.findCallees(functionName);

  if (!callees || callees.length === 0) {
    output.push(`${"  ".repeat(depth + 1)}(No further calls)`);
    return output;
  }

  for (const callee of callees) {
    output.push(`${"  ".repeat(depth + 1)}↓ ${callee.callee}()`);

    output.push(
      ...buildExecutionTree(
        callee.callee,
        visited,
        depth + 2
      )
    );
  }

  return output;
}

function analyzeFunction(functionName) {
  const results = projectSearch.findFunction(functionName);

  if (results.length === 0) {
    return {
      found: false
    };
  }

  const file = results[0];

  // Prefer the complete function body stored in the project index.
  // Fall back to reading the source file for older indexes.
  let code = file.body || "";

  if (!code) {
    const fullPath = path.join(process.cwd(), file.file);

    if (fs.existsSync(fullPath)) {
      const lines = fs.readFileSync(fullPath, "utf8").split("\n");
      const startLine = Math.max(0, file.line - 3);
      const endLine = Math.min(lines.length, file.line + 4);

      code = lines
        .slice(startLine, endLine)
        .map((line, index) => {
          const lineNumber = startLine + index + 1;
          return `${lineNumber}  ${line}`;
        })
        .join("\n");
    }
  }

  const calls = file.calls || [];
  const body = code;

  // -----------------------------
  // Function Intelligence
  // -----------------------------

  const intelligence = [];

  // Input validation
  if (
    /if\s*\(\s*!?\s*[A-Za-z_][A-Za-z0-9_]*/.test(body) &&
    /throw new Error/i.test(body)
  ) {
    intelligence.push("Validates input and rejects invalid data.");
  }

  // Reads data
  if (
    /\b(get[A-Z][A-Za-z0-9_]*|read[A-Z][A-Za-z0-9_]*)\s*\(/.test(body) ||
    /\breadJson\s*\(/.test(body) ||
    /\breadFile\s*\(/.test(body)
  ) {
    intelligence.push("Reads existing data before performing its operation.");
  }

  // Writes data
  if (
    /\b(save[A-Z][A-Za-z0-9_]*|write[A-Z][A-Za-z0-9_]*)\s*\(/.test(body) ||
    /\bwriteJson\s*\(/.test(body) ||
    /\bwriteFile\s*\(/.test(body)
  ) {
    intelligence.push("Writes or persists data.");
  }

  // Array search / duplicate detection
  if (
    /\.find\s*\(/.test(body) ||
    /\.findIndex\s*\(/.test(body)
  ) {
    intelligence.push("Searches a collection to locate an existing item.");
  }

  // Array insertion
  if (
    /\.push\s*\(/.test(body)
  ) {
    intelligence.push("Adds a new item to a collection.");
  }

  // Object creation
  if (
    /const\s+[A-Za-z_][A-Za-z0-9_]*\s*=\s*\{/.test(body)
  ) {
    intelligence.push("Constructs an object containing processed data.");
  }

  // Return behavior
  if (/return\s+\[\s*\]/.test(body)) {
    intelligence.push("Can return an empty collection when no data exists.");
  }

  if (/return\s+new[A-Za-z0-9_]*/.test(body)) {
    intelligence.push("Returns newly created data.");
  }

  if (/return\s+[A-Za-z_][A-Za-z0-9_]*/.test(body)) {
    intelligence.push("Returns a computed or retrieved value.");
  }

  // Async behavior
  if (/async\s+function/.test(body) || /\bawait\s+/.test(body)) {
    intelligence.push("Performs asynchronous operations.");
  }

  // Calls detected by the project index
  if (calls.length > 0) {
    const uniqueCalls = [
      ...new Set(calls.map(call => call.name))
    ];

    intelligence.push(
      `Uses project functions: ${uniqueCalls.map(name => `${name}()`).join(", ")}.`
    );
  }

  if (intelligence.length === 0) {
    intelligence.push(
      "Purpose could not be inferred automatically from the indexed code."
    );
  }

  // -----------------------------
  // Summary
  // -----------------------------

  let summary = `This function is named ${functionName}.`;

  if (
    /customer/i.test(functionName) &&
    /\.push\s*\(/.test(body) &&
    /saveCustomers\s*\(/.test(body)
  ) {
    summary =
      "Adds a customer to the business customer list, prevents duplicate customer IDs, and saves the updated customer data.";
  } else if (/remember/i.test(functionName)) {
    summary =
      "Stores important user information into SamuAI's long-term memory and updates the saved profile.";
  } else if (/search/i.test(functionName)) {
    summary =
      "Searches the project index to locate files, functions or dependencies.";
  } else if (/load/i.test(functionName)) {
    summary =
      "Loads information from disk into memory.";
  } else if (/save/i.test(functionName)) {
    summary =
      "Writes information from memory back to disk.";
  }

  // -----------------------------
  // Callers
  // -----------------------------

  const callers = projectSearch.findCallers(functionName);

  const callerText =
    callers.length > 0
      ? callers
          .map(c => `• ${c.file} — Line ${c.line}`)
          .join("\n")
      : "No callers found.";

  // -----------------------------
  // Dependencies
  // -----------------------------

  const dependencyText =
    file.requires && file.requires.length > 0
      ? file.requires
          .map(r => `• ${r.module} — Line ${r.line}`)
          .join("\n")
      : "No dependencies found.";

  const intelligenceText = intelligence
    .map(item => `• ${item}`)
    .join("\n");

  return {
    found: true,
    summary,
    intelligence,
    file,
    callers,
    dependencies: file.requires || [],
    calls,
    code,

    reply:
`🧠 Function Analysis

Function: ${functionName}()

📖 Summary:
${summary}

🧠 Function Intelligence:
${intelligenceText}

📍 Defined in:
${file.file} — Line ${file.line}

🔗 Called from:
${callerText}

📞 Calls:
${
  calls.length > 0
    ? calls
        .map(c => `• ${c.name}() — Line ${c.line}`)
        .join("\n")
    : "No project functions called."
}

📦 Dependencies:
${dependencyText}

📝 Code:
${code}`
  };
}

module.exports = {
  analyzeFunction
};

.map((line, index) => {
  const lineNumber = startLine + index + 1;
  return `${lineNumber}  ${line}`;
})

function listFunctions(fileName) {

  const index = projectSearch.loadIndex();

  const file = index.find(f => f.file.endsWith(fileName));

  if (!file) {
    return {
      found: false
    };
  }

  const functions = [
    ...file.functions,
    ...file.arrowFunctions
  ];

  if (functions.length === 0) {
    return {
      found: true,
      reply:
`📄 ${file.file}

No functions found.`
    };
  }

  return {
    found: true,
    reply:
`📄 ${file.file}

Functions:

${functions
  .map(f => `• ${f.name}() — Line ${f.line}`)
  .join("\n")}

  Total: ${functions.length}`
    };
}

function analyzeFunctionImpact(functionName) {
  const results = projectSearch.findFunction(functionName);

  if (results.length === 0) {
    return {
      found: false
    };
